// Get webhook data and quotes from Supabase
const webhookData = $input.first().json.body || {};
const quotes = $input.all()[0].json.data || [];

// Ensure we have at least 2 quotes to compare
if (quotes.length < 2) {
  return [{
    json: {
      error: true,
      message: 'Need at least 2 quotes for comparison',
      quote_count: quotes.length,
      job_id: webhookData.job_id
    }
  }];
}

// Build job details
const jobDetails = {
  description: webhookData.job_description || 'Property maintenance work',
  property_address: webhookData.property_address || 'Property address not provided',
  deadline: webhookData.deadline || 'Not specified'
};

// Format quotes for AI analysis
const formattedQuotes = quotes.map((quote, index) => {
  const quoteNum = index + 1;
  return {
    number: quoteNum,
    id: quote.id,
    contractor_name: quote.contractor_name || `Contractor ${quoteNum}`,
    contractor_phone: quote.contractor_phone || '',
    contractor_email: quote.contractor_email || '',
    amount: quote.quote_amount || 0,
    text: quote.quote_text || 'No detailed quote provided',
    received_at: quote.received_at
  };
});

// Build Groq prompt
const buildPrompt = (job, quotesList) => {
  let prompt = `Compare these contractor quotes for the same job:

JOB DETAILS:
Description: ${job.description}
Property: ${job.property_address}
Required Completion: ${job.deadline}

`

  quotesList.forEach((q, i) => {
    prompt += `QUOTE ${i + 1}:
Contractor: ${q.contractor_name}
Total: R${q.amount.toLocaleString()}
Quote Text: ${q.text}

`;
  });

  prompt += `Analyze and return JSON with:
- comparison_summary (lowest_price, highest_price, price_range)
- line_item_comparison (array of compared items with prices)
- scope_analysis (inclusions/exclusions per quote)
- risk_assessment (per contractor with risk_level, concerns, positives)
- recommendation (recommended_contractor, reasoning, confidence, negotiation_suggestions)
- missing_information (array of what to ask)
- total_value_score (1-10 rating per quote)

Return ONLY valid JSON, no markdown formatting.`;

  return prompt;
};

const prompt = buildPrompt(jobDetails, formattedQuotes);

return [{
  json: {
    job_id: webhookData.job_id,
    property_id: webhookData.property_id,
    job_details: jobDetails,
    quotes: formattedQuotes,
    quote_count: quotes.length,
    prompt: prompt
  }
}];

// Parse Groq AI response
try {
  const aiResponse = $input.first().json;
  const choice = aiResponse.choices && aiResponse.choices[0];

  if (!choice) {
    throw new Error('No choices in AI response');
  }

  const content = choice.message?.content || choice.text;
  let parsedAnalysis;

  try {
    parsedAnalysis = JSON.parse(content);
  } catch (parseError) {
    // Try to extract JSON from markdown code blocks
    const jsonMatch = content.match(/```(?:json)?\s*([\s\S]*?)```/);
    if (jsonMatch) {
      parsedAnalysis = JSON.parse(jsonMatch[1].trim());
    } else {
      throw new Error('Could not parse AI response as JSON');
    }
  }

  // Validate required fields
  const requiredFields = ['comparison_summary', 'recommendation', 'risk_assessment'];
  const missingFields = requiredFields.filter(f => !parsedAnalysis[f]);

  if (missingFields.length > 0) {
    console.warn('Missing fields in AI response:', missingFields);
  }

  return [{
    json: {
      success: true,
      comparison_summary: parsedAnalysis.comparison_summary || {},
      line_item_comparison: parsedAnalysis.line_item_comparison || [],
      scope_analysis: parsedAnalysis.scope_analysis || {},
      risk_assessment: parsedAnalysis.risk_assessment || [],
      recommendation: parsedAnalysis.recommendation || {},
      missing_information: parsedAnalysis.missing_information || [],
      total_value_score: parsedAnalysis.total_value_score || {},
      ai_model: aiResponse.model,
      tokens_used: aiResponse.usage?.total_tokens || 0
    }
  }];
} catch (error) {
  return [{
    json: {
      success: false,
      error: error.message,
      raw_response: $input.first().json
    }
  }];
}

// Prepare data for saving
const webhookData = $('Quote Comparison Webhook').first().json.body;
const prepData = $('Prepare Comparison Data').first().json;
const parsedData = $input.first().json;

if (!parsedData.success) {
  return [{
    json: {
      error: 'AI parsing failed',
      details: parsedData.error
    }
  }];
}

return [{
  json: {
    job_id: webhookData.job_id,
    property_id: webhookData.property_id,
    job_description: prepData.job_details.description,
    quotes: prepData.quotes,
    comparison_summary: parsedData.comparison_summary,
    line_item_comparison: parsedData.line_item_comparison,
    scope_analysis: parsedData.scope_analysis,
    risk_assessment: parsedData.risk_assessment,
    recommendation: parsedData.recommendation,
    missing_information: parsedData.missing_information,
    total_value_score: parsedData.total_value_score
  }
}];

// Prepare final response
const parsedData = $input.first().json;

if (!parsedData.success) {
  return [{
    json: {
      status: 'error',
      message: parsedData.error,
      recommendation: null
    }
  }];
}

return [{
  json: {
    status: 'success',
    message: 'Quote comparison completed',
    comparison: {
      summary: parsedData.comparison_summary,
      line_items: parsedData.line_item_comparison,
      scope: parsedData.scope_analysis,
      risks: parsedData.risk_assessment,
      recommendation: parsedData.recommendation,
      missing_info: parsedData.missing_information,
      value_scores: parsedData.total_value_score
    },
    next_steps: [
      'Review comparison report in PropAgent dashboard',
      'Contact recommended contractor to discuss details',
      'Request missing information from all contractors',
      'Negotiate based on comparison insights'
    ]
  }
}];

// Handle errors and edge cases
const input = $input.first().json;

// Check if error from previous nodes
if (input.error) {
  return [{
    json: {
      status: 'error',
      error_type: input.error === true ? 'validation_error' : 'processing_error',
      message: input.message || input.error || 'Unknown error occurred',
      quote_count: input.quote_count || 0,
      job_id: input.job_id || 'unknown'
    }
  }];
}

// Check if insufficient quotes
if (input.quote_count < 2) {
  return [{
    json: {
      status: 'insufficient_quotes',
      message: `Only ${input.quote_count} quote(s) received. Need at least 2 for comparison.`,
      quote_count: input.quote_count,
      job_id: input.job_id
    }
  }];
}

// Pass through successful data
return $input.all();
